mapper.update:
UPDATE certificate
SET status        = 'REVOKED',
    revoked_at    = NOW(),
    revoke_reason = #{reason}
WHERE pilgrimage_id = #{pilgrimageId}
  AND status = 'VALID'

UPDATE certificate
SET status        = 'REVOKED',
    revoked_at    = NOW(),
    revoke_reason = #{reason}
WHERE certificate_id = #{certificateId}
  AND status = 'VALID'

UPDATE certificate
SET status        = 'REVOKED',
    revoked_at    = NOW(),
    revoke_reason = #{reason}
WHERE user_id = #{userId}
  AND status = 'VALID'

UPDATE certificate
SET status        = 'REVOKED',
    revoked_at    = NOW(),
    revoke_reason = #{reason}
WHERE user_id = #{userId}
  AND cert_type = #{certType}
  AND status = 'VALID'
